-- exmd5-5.hs: extended Minsky doubling (value x5, 5 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 5^5 = 3125.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x5
exmd (x, 0,    2) = exmd (  x,   0,    8)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    5)
exmd (x, y,    5) = exmd (x+1,   y,    6)
exmd (x, y,    6) = exmd (x+1,   y,    7)
exmd (x, y,    7) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=8): x -> y, x5
exmd (0, y,    8) = exmd (  0,   y,   14)
exmd (x, y,    8) = exmd (x-1,   y,    9)
exmd (x, y,    9) = exmd (  x, y+1,   10)
exmd (x, y,   10) = exmd (  x, y+1,   11)
exmd (x, y,   11) = exmd (  x, y+1,   12)
exmd (x, y,   12) = exmd (  x, y+1,   13)
exmd (x, y,   13) = exmd (  x, y+1,    8)

-- Cycle 2 (pc=14): y -> x, x5
exmd (x, 0,   14) = exmd (  x,   0,   20)
exmd (x, y,   14) = exmd (  x, y-1,   15)
exmd (x, y,   15) = exmd (x+1,   y,   16)
exmd (x, y,   16) = exmd (x+1,   y,   17)
exmd (x, y,   17) = exmd (x+1,   y,   18)
exmd (x, y,   18) = exmd (x+1,   y,   19)
exmd (x, y,   19) = exmd (x+1,   y,   14)

-- Cycle 3 (pc=20): x -> y, x5
exmd (0, y,   20) = exmd (  0,   y,   26)
exmd (x, y,   20) = exmd (x-1,   y,   21)
exmd (x, y,   21) = exmd (  x, y+1,   22)
exmd (x, y,   22) = exmd (  x, y+1,   23)
exmd (x, y,   23) = exmd (  x, y+1,   24)
exmd (x, y,   24) = exmd (  x, y+1,   25)
exmd (x, y,   25) = exmd (  x, y+1,   20)

-- Cycle 4 (pc=26): y -> x, x5
exmd (x, 0,   26) = exmd (  x,   0,   32)
exmd (x, y,   26) = exmd (  x, y-1,   27)
exmd (x, y,   27) = exmd (x+1,   y,   28)
exmd (x, y,   28) = exmd (x+1,   y,   29)
exmd (x, y,   29) = exmd (x+1,   y,   30)
exmd (x, y,   30) = exmd (x+1,   y,   31)
exmd (x, y,   31) = exmd (x+1,   y,   26)

-- Drain (pc=32): DEC x to 0, then HALT
exmd (0, y,   32) = (  0,   y,    1)
exmd (x, y,   32) = exmd (x-1,   y,   32)
